function scheduleSave(){$("#saveState").classList.add("is-saving");clearTimeout(persistTimer);persistTimer=setTimeout(persist,220);}
function escapeHtml(value){return String(value??"").replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]));}
const escapeXml=escapeHtml;
function toast(message){const el=$("#toast");el.textContent=message;el.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove("show"),2500);}
function applyLanguage(){document.documentElement.lang=state.lang==="en"?"en":"pt-BR";$$("[data-i18n]").forEach(el=>{const key=el.dataset.i18n;if(t(key))el.textContent=t(key);});$$("[data-i18n-html]").forEach(el=>{const key=el.dataset.i18nHtml;if(t(key))el.innerHTML=t(key);});$$("[data-i18n-placeholder]").forEach(el=>{const key=el.dataset.i18nPlaceholder;if(t(key))el.placeholder=t(key);});$("#languageToggle").textContent=state.lang==="en"?"PT":"EN";$("#sectionKicker").textContent=t("section")[state.step]||t("section")[0];$("#projectNamePreview").textContent=state.projectName||(state.lang==="en"?"New project":"Novo projeto");}
function applyStateToInputs(){["projectName","systemKind","brief","volume","availability","sensitivity","team","integrations","consistency","independentDeploy","storage","roiVolume","minutesSaved","hourlyCost","runCost","implementationCost"].forEach(id=>{const el=$("#"+id);if(el&&state[id]!==undefined)el.value=state[id];});["topology","codeShape","communication"].forEach(name=>{const selected=$('input[name="'+name+'"][value="'+state[name]+'"]');if(selected)selected.checked=true;});$("#ollamaUrl").value=state.ollamaUrl;updateCounters();updateEconomics();$("#projectNamePreview").textContent=state.projectName;renderRationale();applyLanguage();}
function readInputs(){["projectName","systemKind","brief","volume","availability","sensitivity","team","integrations","consistency","independentDeploy","storage","roiVolume","minutesSaved","hourlyCost","runCost","implementationCost"].forEach(id=>{const el=$("#"+id);if(el)state[id]=el.value;});["topology","codeShape","communication"].forEach(name=>{const selected=$('input[name="'+name+'"]:checked');if(selected)state[name]=selected.value;});state.projectName=state.projectName.trim();$("#projectNamePreview").textContent=state.projectName||(state.lang==="en"?"New project":"Novo projeto");}
function updateCounters(){$("#briefCount").textContent=String($("#brief").value.length);}
function money(value){return new Intl.NumberFormat(state.lang==="en"?"en-US":"pt-BR",{style:"currency",currency:"BRL",maximumFractionDigits:0}).format(Number.isFinite(value)?value:0);}
function updateEconomics(){const volume=Math.max(0,Number($("#roiVolume").value)||0),mins=Math.max(0,Number($("#minutesSaved").value)||0),hourly=Math.max(0,Number($("#hourlyCost").value)||0),run=Math.max(0,Number($("#runCost").value)||0),build=Math.max(0,Number($("#implementationCost").value)||0);const benefit=volume*mins/60*hourly*12,net=benefit-run*12-build,total=build+run*12;$("#annualBenefitValue").textContent=money(benefit);$("#yearOneNetValue").textContent=money(net);$("#roiValue").textContent=total>0?((net/total)*100).toFixed(1).replace(".",state.lang==="pt"?",":".")+"%":"—";}
function setStep(index){if(index>0&&!$("#brief").value.trim()){toast(t("needBrief"));$("#brief").focus();return;}state.step=Math.max(0,Math.min(3,index));$$(".step-panel").forEach((panel,i)=>panel.hidden=i!==state.step);$$(".rail-step").forEach((button,i)=>{button.classList.toggle("active",i===state.step);if(i===state.step)button.setAttribute("aria-current","step");else button.removeAttribute("aria-current");});$("#progressFill").style.width=((state.step+1)*25)+"%";$("#progressLabel").textContent=((state.step+1)*25)+"%";$("#sectionKicker").textContent=t("section")[state.step];if(state.step===2)renderRationale();if(state.step===3){renderRecommendation();renderArtifact(state.artifact);}scheduleSave();if(window.matchMedia("(max-width:760px)").matches)$("#workArea")?.scrollIntoView({behavior:"smooth",block:"start"});}
function getOpenQuestions(){const q=copy[state.lang].questions,list=[];if(state.brief.length<70)list.push(q.role);if(!/conclu|resultado|sucesso|status|aprov|done|complete|success|status/i.test(state.brief))list.push(q.success);if(!/duplic|repet|idempot|retry|twice|again/i.test(state.brief))list.push(q.repeat);if(state.availability==="unknown"||state.availability==="business")list.push(q.availability);if(state.team==="unknown")list.push(q.owner);return [...new Set(list)].slice(0,4);}
function fallbackMap(){const text=state.brief.trim(),sentences=text.split(/(?<=[.!?])\s+|;\s*/).filter(Boolean).slice(0,6),terms=state.lang==="en"?[["approv","Approval / authorization"],["pay","Payment"],["document","Document reading or extraction"],["access","Access management"],["integrat","External integration"],["audit","Audit trail"],["event","Asynchronous processing"],["notif","Notification"]]:[["aprova","Aprovação / autorização"],["pag","Pagamento"],["document","Leitura ou extração de documentos"],["acesso","Gestão de acessos"],["integra","Integração externa"],["audit","Trilha de auditoria"],["evento","Processamento assíncrono"],["notifica","Notificação"]];const capabilities=terms.filter(([key])=>text.toLowerCase().includes(key)).map(([,label])=>label);return {summary:sentences.slice(0,2).join(" "),capabilities:capabilities.length?capabilities:[state.lang==="en"?"Capture the request and its outcome":"Registrar a solicitação e seu resultado"],unknowns:getOpenQuestions(),origin:"local"};}
function renderMap(map,origin){const caps=(map.capabilities||[]).filter(item=>typeof item==="string").slice(0,8),unknowns=(map.unknowns||getOpenQuestions()).filter(item=>typeof item==="string").slice(0,5),summary=escapeHtml(typeof map.summary==="string"&&map.summary.trim()?map.summary:state.brief),label=origin==="ollama"?t("llmUsed"):t("localFallback");$("#advisorContent").innerHTML="<div class=\"analysis-label\">"+escapeHtml(label)+"</div><p><strong>"+escapeHtml(t("missingTitle"))+":</strong> "+summary+"</p><strong>"+escapeHtml(t("capabilities"))+"</strong><ul>"+caps.map(item=>"<li>"+escapeHtml(item)+"</li>").join("")+"</ul><strong>"+escapeHtml(t("openQuestions"))+"</strong><ul>"+unknowns.map(item=>"<li>"+escapeHtml(item)+"</li>").join("")+"</ul><p class=\"confidence-note\">"+escapeHtml(t("factsOnly"))+"</p>";$("#briefAdvisor").hidden=false;state.advisor={summary:map.summary,capabilities:caps,unknowns,origin};scheduleSave();}
async function callOllama(messages,json=false){const url=($("#ollamaUrl").value||state.ollamaUrl).trim().replace(/\/+$/,""),model=$("#ollamaModel").value||state.ollamaModel;if(!model)throw new Error("model");const payload={model,messages,stream:false,options:{temperature:0.2,num_predict:750}};if(json)payload.format="json";const response=await fetch(url+"/api/chat",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});if(!response.ok)throw new Error("request");const result=await response.json();return result.message?.content||"";}
async function analyzeBrief(){readInputs();if(!state.brief.trim()){toast(t("noBrief"));$("#brief").focus();return;}const btn=$("#analyzeBrief");btn.disabled=true;btn.textContent=t("analyzing");try{if(ollamaConnected&&$("#ollamaModel").value){const system="You are a senior software architect. Read the product brief and return only JSON with fields summary (string), capabilities (array of strings), unknowns (array of questions). Work only with facts present in the brief. Do not invent users, metrics, controls, costs, or implementation results. Use concise Brazilian Portuguese if the brief is Portuguese; otherwise English. Maximum 6 capabilities and 5 questions.";const raw=await callOllama([{role:"system",content:system},{role:"user",content:state.brief}],true),map=JSON.parse(raw);if(!map||typeof map.summary!=="string"||!Array.isArray(map.capabilities)||!Array.isArray(map.unknowns))throw new Error("invalid model response");renderMap(map,"ollama");}else renderMap(fallbackMap(),"local");}catch{renderMap(fallbackMap(),"local");toast(t("connectionFailed"));}finally{btn.disabled=false;btn.innerHTML="<span>✦</span><span>"+escapeHtml(t("analyzeBrief"))+"</span>";}}
function answerLocally(question){const q=question.toLowerCase(),en=state.lang==="en";if(/keycloak|login|auth|autent|acesso|identity/.test(q))return en?"Use Keycloak as the OIDC identity provider. The Java API should validate signed access tokens, issuer and audience, then map roles or scopes to business permissions. Keep authorization policy in the API; identity alone does not decide what a user may do.":"Use Keycloak como provedor de identidade OIDC. A API Java deve validar assinatura, emissor e audience do access token e mapear roles ou scopes para permissões de negócio. Mantenha a política de autorização na API; identidade sozinha não decide o que a pessoa pode fazer.";if(/microserv|serviç|service|deploy|implanta/.test(q))return en?"Split services when separate teams own the domains, need independent deployment or scaling, and can operate the added network, data, and observability complexity. A modular monolith keeps boundaries while deferring that operational cost.":"Divida em serviços quando times diferentes forem donos dos domínios, houver necessidade de deploy ou escala independente e a organização puder operar a complexidade de rede, dados e observabilidade. Um monólito modular preserva fronteiras e adia esse custo operacional.";if(/event|assíncr|async|fila|queue|consist/.test(q))return en?"Use asynchronous events only where the business accepts delayed completion. Define idempotency, retry limits, dead-letter handling, ordering, and reconciliation before relying on the broker for business workflows.":"Use eventos assíncronos somente onde o negócio aceita conclusão posterior. Defina idempotência, limite de tentativas, fila de mensagens mortas, ordenação e reconciliação antes de tratar o broker como infraestrutura confiável de fluxo.";if(/roi|retorno|custo|cost|valor|econom/.test(q))return en?"The estimate uses your inputs: monthly volume × minutes saved × loaded hourly cost × 12. Year-one ROI subtracts initial investment and 12 months of operating cost. It omits adoption, opportunity cost, taxes, integration effort, and uncertainty; validate each input with the business.":"A estimativa usa seus dados: operações mensais × minutos poupados × custo-hora carregado × 12. O ROI do primeiro ano desconta o investimento inicial e 12 meses de operação. Não inclui adoção, custo de oportunidade, tributos, esforço de integração nem incerteza; valide cada premissa com o negócio.";if(/database|banco|persist|dados|storage/.test(q))return en?"Choose storage from retention, integrity, query, recovery, and audit needs. This scaffold uses PostgreSQL when selected; if an approved data platform already exists, treat it as an external dependency rather than adding another database by default.":"Escolha a persistência pelos requisitos de retenção, integridade, consulta, recuperação e auditoria. O esqueleto usa PostgreSQL quando selecionado; se a empresa já tem uma plataforma aprovada, trate-a como dependência externa em vez de adicionar outro banco por padrão.";if(/api|rest|http/.test(q))return en?"REST is reasonable when a caller needs a synchronous answer and resource-oriented contracts fit. Confirm authentication, authorization, idempotency, rate limits, error semantics, and API ownership before publishing it.":"REST é um padrão inicial razoável quando o cliente precisa de resposta síncrona e o contrato orientado a recursos se encaixa. Defina autenticação, autorização, idempotência, limites de uso, semântica de erros e propriedade da API antes de publicá-la.";return en?"Start with the user and business outcome, then make one decision at a time: deployment boundary, code organization, communication, data ownership, identity, and operating constraints. The diagram is a draft; confirm each assumption with the owning team.":"Comece pela pessoa usuária e pelo resultado de negócio; depois decida uma dimensão por vez: fronteira de implantação, organização do código, comunicação, propriedade dos dados, identidade e operação. O diagrama é um rascunho; confirme cada premissa com o time responsável.";}
async function askAdvisor(event){event.preventDefault();const question=$("#advisorQuestion").value.trim();if(!question)return;$("#advisorQuestion").value="";chat.push({role:"user",text:question});renderChat();if(ollamaConnected&&$("#ollamaModel").value){const context=JSON.stringify({brief:state.brief,choices:{topology:state.topology,codeShape:state.codeShape,communication:state.communication},constraints:{availability:state.availability,sensitivity:state.sensitivity,team:state.team,integrations:state.integrations,consistency:state.consistency,storage:state.storage},economics:{volume:state.roiVolume,minutesSaved:state.minutesSaved,hourlyCost:state.hourlyCost,runCost:state.runCost,implementationCost:state.implementationCost}});const history=chat.slice(-6).map(item=>({role:item.role==="assistant"?"assistant":"user",content:item.text}));try{const answer=await callOllama([{role:"system",content:"You are a careful Java software architect speaking "+(state.lang==="en"?"English":"Brazilian Portuguese")+". Answer only from the supplied brief and choices. Label assumptions, ask a clarifying question when evidence is missing, and never invent costs, benchmarks, compliance requirements, or operational facts. Give concise, actionable advice. Context: "+context},...history]);chat.push({role:"assistant",text:answer,source:"ollama"});}catch{chat.push({role:"assistant",text:answerLocally(question),source:"heuristic"});toast(t("connectionFailed"));}}else chat.push({role:"assistant",text:answerLocally(question),source:"heuristic"});renderChat();scheduleSave();}
function renderChat(){$("#chatLog").innerHTML=chat.slice(-8).map(item=>"<div class=\"chat-message "+(item.role==="user"?"user":"")+"\">"+(item.role==="assistant"?"<small class=\"chat-source\">"+escapeHtml(item.source==="ollama"?t("chatOllamaSource"):t("chatFallbackSource"))+"</small>":"")+escapeHtml(item.text)+"</div>").join("");$("#chatLog").scrollTop=$("#chatLog").scrollHeight;}



function labels(){return {topology:state.topology==="microservices"?t("topologyMicro"):t("topologyModular"),shape:state.codeShape==="hexagonal"?t("shapeHex"):t("shapeLayered"),communication:state.communication==="async"?t("commAsync"):t("commSync")};}
function getConcerns(){const concerns=[];if(state.topology==="microservices"&&(state.team==="small"||state.team==="unknown")&&state.independentDeploy!=="must")concerns.push(t("microCaution"));if(state.communication==="async"&&state.consistency==="strong")concerns.push(t("asyncCaution"));if(state.sensitivity==="personal"||state.sensitivity==="regulated")concerns.push(t("securityCaution"));return concerns;}
function renderRationale(){const value=labels(),concerns=getConcerns(),operating=state.topology==="microservices"||state.communication==="async"?"costHigh":(state.codeShape==="hexagonal"||state.integrations!=="few"?"costMedium":"costLow"),concernText=concerns[0]||t("fitGood");$("#architectureRationale").innerHTML="<div class=\"rationale-card\"><small>"+escapeHtml(t("topology"))+"</small><strong>"+escapeHtml(value.topology)+"</strong><p>"+escapeHtml(operating==="costLow"?t("modularDesc"):operating==="costMedium"?t("hexDesc"):t("microDesc"))+"</p></div><div class=\"rationale-card\"><small>"+escapeHtml(t("internal"))+"</small><strong>"+escapeHtml(value.shape)+"</strong><p>"+escapeHtml(state.codeShape==="hexagonal"?t("hexDesc"):t("layeredDesc"))+"</p></div><div class=\"rationale-card "+(concerns.length?"warning":"")+"\"><small>"+escapeHtml(concerns.length?t("caution"):t("communication"))+"</small><strong>"+escapeHtml(concernText.length>83?concernText.slice(0,80)+"…":concernText)+"</strong><p>"+escapeHtml(state.communication==="async"?t("eventDesc"):t("restDesc"))+"</p></div>";}
function safeName(value){return String(value||"system").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"").slice(0,40)||"system";}
function svgBox(x,y,w,h,heading,title,description,color="#15384a"){const compact=h<=64,titleY=y+(compact?38:47),descriptionY=y+(compact?53:67),titleSize=compact?12:14,descriptionSize=compact?8:9;return "<g><rect x=\""+x+"\" y=\""+y+"\" width=\""+w+"\" height=\""+h+"\" rx=\"10\" fill=\""+color+"\" stroke=\"#5b879c\" stroke-width=\"1.2\"/><text x=\""+(x+14)+"\" y=\""+(y+20)+"\" fill=\"#9ab1c2\" font-size=\"8\" class=\"mono\" letter-spacing=\"1\">"+escapeXml(heading)+"</text><text x=\""+(x+14)+"\" y=\""+titleY+"\" fill=\"#eef7fb\" font-size=\""+titleSize+"\" font-weight=\"700\">"+escapeXml(title)+"</text><text x=\""+(x+14)+"\" y=\""+descriptionY+"\" fill=\"#aac0cf\" font-size=\""+descriptionSize+"\">"+escapeXml(description)+"</text></g>";}
function svgArrow(x1,y1,x2,y2,label,dashed=false){return "<g><title>"+escapeXml(label)+"</title><line x1=\""+x1+"\" y1=\""+y1+"\" x2=\""+x2+"\" y2=\""+y2+"\" stroke=\"#75cbd3\" stroke-width=\"1.4\" "+(dashed?"stroke-dasharray=\"5 4\" ":"")+"marker-end=\"url(#arrow)\"/></g>";}
function svgShell(title,body,width=900,height=330){return "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 "+width+" "+height+"\" role=\"img\" aria-label=\""+escapeXml(title)+"\"><rect width=\"100%\" height=\"100%\" fill=\"#071522\"/><defs><style>text{font-family:Arial,sans-serif}.mono{font-family:monospace}</style><marker id=\"arrow\" markerWidth=\"8\" markerHeight=\"8\" refX=\"7\" refY=\"4\" orient=\"auto\"><path d=\"M0 0L8 4L0 8z\" fill=\"#75cbd3\"/></marker></defs><text x=\"22\" y=\"24\" fill=\"#66e4f1\" font-size=\"8\" class=\"mono\" letter-spacing=\"2\">"+escapeXml(title.toUpperCase())+"</text>"+body+"</svg>";}
function c4ContextSvg(){const arrows=svgArrow(235,158,341,158,t("relUses"))+svgArrow(609,158,667,158,t("relAuth"));const boxes=svgBox(36,112,195,91,"PERSON",state.lang==="en"?"Business user":"Pessoa usuária",t("clientActor"),"#123047")+svgBox(345,95,260,126,"SOFTWARE SYSTEM",state.projectName||t("system"),t("systemDescription"),"#164251")+svgBox(671,112,195,91,"EXTERNAL SYSTEM","Keycloak",t("externalIdentity"),"#343056");const note="<text x=\"24\" y=\"294\" fill=\"#8298aa\" font-size=\"9\">"+escapeXml(t("contextRelations"))+"</text>";return svgShell(t("ctxTitle"),arrows+boxes+note,900,330);}
function c4ContainerSvg(){
  const async=state.communication==="async",hasStorage=state.storage!=="none",externalStorage=state.storage==="external";
  const boundary="<rect x=\"164\" y=\"52\" width=\"482\" height=\"260\" rx=\"13\" fill=\"#0b1c2b\" fill-opacity=\".6\" stroke=\"#36566b\" stroke-dasharray=\"5 4\"/><text x=\"179\" y=\"72\" fill=\"#87a6b9\" font-size=\"8\" class=\"mono\">"+escapeXml((state.projectName||t("system"))+" · "+t("containerTitle"))+"</text>";
  const dbX=externalStorage?700:(async?194:408),dbY=externalStorage?72:242;
  const db=hasStorage?svgBox(dbX,dbY,174,60,externalStorage?"EXTERNAL SYSTEM":"CONTAINER",externalStorage?t("externalDb"):t("db"),externalStorage?t("externalDbDesc"):t("databaseDesc"),"#302d50"):"";
  const broker=async?svgBox(408,242,202,60,"CONTAINER",t("broker"),t("brokerDesc"),"#3a3245"):"";
  const arrows=svgArrow(148,166,190,166,t("relUses"))+svgArrow(375,166,404,166,t("relCalls"))+(hasStorage?(externalStorage?svgArrow(614,166,696,102,t("relStores")):(async?svgArrow(404,194,372,272,t("relStores")):svgArrow(509,221,509,238,t("relStores")))):"")+svgArrow(614,166,696,244,t("relAuth"))+(async?svgArrow(509,221,509,238,t("relPublishes")):"");
  const boxes=svgBox(24,123,120,90,"PERSON",state.lang==="en"?"User":"Pessoa",t("clientActor"),"#123047")+svgBox(194,109,177,108,"CLIENT",t("browser"),state.systemKind==="web"?(state.lang==="en"?"Business UI":"Interface de negócio"):(state.lang==="en"?"Calling system":"Sistema cliente"),"#27324b")+svgBox(408,109,202,108,"CONTAINER",t("api"),t("containerApiDesc"),"#164251")+db+svgBox(700,205,174,78,"EXTERNAL SYSTEM",t("idp"),t("keycloakDesc"),"#343056")+broker;
  const note="<text x=\"24\" y=\"340\" fill=\"#8298aa\" font-size=\"9\">"+escapeXml(t("containerRelations"))+"</text>";
  return svgShell(t("containerTitle"),boundary+arrows+boxes+note,900,350);
}
function sequenceSvg(){
  const async=state.communication==="async",store=state.storage,db=store==="postgres"?t("seqDb"):store==="external"?t("externalDb"):t("seqMemory");
  const participants=async?[t("seqUser"),t("seqApi"),t("seqUseCase"),t("seqRepo"),db,t("seqBroker"),t("seqConsumer")]:[t("seqUser"),t("seqApi"),t("seqUseCase"),t("seqRepo"),db];
  const positions=participants.map((_,i)=>70+i*(760/(participants.length-1)));let body="";
  participants.forEach((person,i)=>{const x=positions[i];body+="<rect x=\""+(x-56)+"\" y=\"42\" width=\"112\" height=\"34\" rx=\"6\" fill=\"#132a3d\" stroke=\"#3b596e\"/><text x=\""+x+"\" y=\"63\" fill=\"#e2edf5\" font-size=\"9\" text-anchor=\"middle\">"+escapeXml(person)+"</text><line x1=\""+x+"\" y1=\"76\" x2=\""+x+"\" y2=\"294\" stroke=\"#355166\" stroke-dasharray=\"4 4\"/>";});
  const actions=async?[[0,1,t("seqRequest")],[1,2,t("seqValidate")],[2,3,t("seqSave")],[3,4,t("relStores")],[2,5,t("seqEvent")],[1,0,t("seqReply")],[5,6,t("seqDelivery")],[6,5,t("seqAck")]]:[[0,1,t("seqRequest")],[1,2,t("seqValidate")],[2,3,t("seqSave")],[3,4,t("seqPersist")],[4,3,t("seqReturn")],[3,2,t("seqReturn")],[2,1,t("seqReturn")],[1,0,t("seqSync")]];
  actions.forEach((action,i)=>{const y=99+i*24;body+="<line x1=\""+positions[action[0]]+"\" y1=\""+y+"\" x2=\""+positions[action[1]]+"\" y2=\""+y+"\" stroke=\"#75cbd3\" stroke-width=\"1.2\" marker-end=\"url(#arrow)\"/><text x=\""+((positions[action[0]]+positions[action[1]])/2)+"\" y=\""+(y-5)+"\" text-anchor=\"middle\" fill=\"#b9cdd9\" font-size=\"7\">"+escapeXml(action[2])+"</text>";});
  body+="<text x=\"25\" y=\"318\" fill=\"#8298aa\" font-size=\"8\">"+escapeXml(t("seqOidcNote")+(async?" · "+t("seqAsync"):""))+"</text>";
  return svgShell(t("diagramSequence"),body,900,330);
}
function markdownDecisions(){const names=labels(),concerns=getConcerns(),text="# "+(state.projectName||t("system"))+"\n\n> "+t("adrStatus")+"\n\n## Context\n\n"+state.brief+"\n\n## Assumptions and constraints\n\n- Volume: "+state.volume+"\n- Availability: "+state.availability+"\n- Data sensitivity: "+state.sensitivity+"\n- Team: "+state.team+"\n- Integrations: "+state.integrations+"\n- Persistence: "+state.storage+"\n- Independent deployment: "+state.independentDeploy+"\n- Communication consistency: "+state.consistency+"\n\n## Decisions\n\n";const adr=[[t("decisionOne"),names.topology,state.topology==="microservices"?t("microCaution"):t("modularDesc")],[t("decisionTwo"),names.shape,state.codeShape==="hexagonal"?t("hexDesc"):t("layeredDesc")],[t("decisionThree"),names.communication,state.communication==="async"?t("asyncCaution"):t("restDesc")],[t("decisionFour"),"Keycloak · OpenID Connect",t("keycloakDev")]];return text+adr.map(row=>"### "+row[0]+"\n\n**Status:** Proposal\n\n**Decision:** "+row[1]+".\n\n**Rationale / review note:** "+row[2]+"\n").join("\n")+"\n## Open trade-offs\n\n"+(concerns.length?concerns.map(item=>"- "+item).join("\n"):"- "+t("fitGood"))+"\n\n## Economic assumptions\n\n- Gross annual modeled benefit: "+$("#annualBenefitValue").textContent+"\n- Initial investment supplied: "+money(Number(state.implementationCost)||0)+"\n- Monthly operating cost supplied: "+money(Number(state.runCost)||0)+"\n- Year-one modeled ROI: "+$("#roiValue").textContent+"\n\nThese figures are user inputs and a simplified model, not a forecast or business case approval.";}
function renderDecisions(){const names=labels(),items=[[t("decisionOne"),names.topology,state.topology==="microservices"?t("microCaution"):t("modularDesc")],[t("decisionTwo"),names.shape,state.codeShape==="hexagonal"?t("hexDesc"):t("layeredDesc")],[t("decisionThree"),names.communication,state.communication==="async"?t("asyncCaution"):t("restDesc")],[t("decisionFour"),"Keycloak · OpenID Connect",t("keycloakDev")]];return "<div class=\"artifact-toolbar\"><strong>"+escapeHtml(t("adrsTitle"))+"</strong><button type=\"button\" data-copy-decisions>"+(state.lang==="en"?"Copy decisions":"Copiar decisões")+"</button></div><div class=\"decision-list\">"+items.map((item,i)=>"<article class=\"decision-item\"><span class=\"decision-num\">0"+(i+1)+"</span><div><h4>"+escapeHtml(item[0])+" · "+escapeHtml(item[1])+"</h4><p>"+escapeHtml(item[2])+"</p><small class=\"adr-label\">"+escapeHtml(t("adrStatus"))+"</small></div></article>").join("")+"</div><p class=\"diagram-note\">"+escapeHtml(t("confidenceText"))+"</p>";}
function diagramMarkup(type){const title=type==="c4-context"?t("diagramContext"):type==="c4-container"?t("diagramContainer"):t("diagramSequence"),svg=type==="c4-context"?c4ContextSvg():type==="c4-container"?c4ContainerSvg():sequenceSvg();lastSvg=svg;return "<div class=\"artifact-toolbar\"><strong>"+escapeHtml(title)+"</strong><div><button type=\"button\" data-diagram-action=\"copy\">"+escapeHtml(t("copyAction"))+"</button> <button type=\"button\" data-diagram-action=\"download\">"+escapeHtml(t("saveSvg"))+"</button></div></div><div class=\"diagram-legend\"><span class=\"legend-chip\"><i></i> "+escapeHtml(t("api"))+"</span><span class=\"legend-chip database\"><i></i> "+escapeHtml(t("db"))+"</span><span class=\"legend-chip external\"><i></i> "+escapeHtml(t("idp"))+"</span></div><div class=\"diagram-wrap\">"+svg+"</div><p class=\"diagram-note\">"+escapeHtml(t("diagramNote"))+"</p>";}
function renderRecommendation(){const names=labels(),concerns=getConcerns(),relative=state.topology==="microservices"||state.communication==="async"?"costHigh":(state.codeShape==="hexagonal"||state.integrations!=="few"?"costMedium":"costLow"),description=concerns[0]||t("confidenceText");$("#recommendationBanner").innerHTML="<div><span class=\"rec-eyebrow\">"+escapeHtml(t("recTitle"))+" · "+escapeHtml(t(relative))+"</span><h3>"+escapeHtml(names.topology)+"</h3><p>"+escapeHtml(names.shape)+" · "+escapeHtml(names.communication)+". "+escapeHtml(description)+"</p></div><span class=\"rec-tag\">"+escapeHtml(t("modelled"))+"</span>";}
function renderArtifact(type){state.artifact=type;$$(".artifact-tab").forEach(tab=>{const active=tab.dataset.artifact===type;tab.classList.toggle("active",active);tab.setAttribute("aria-selected",active?"true":"false");});const panel=$("#artifactPanel");if(type==="decision")panel.innerHTML=renderDecisions();else if(type==="starter")panel.innerHTML=renderStarter();else panel.innerHTML=diagramMarkup(type==="sequence"?"sequence":type);scheduleSave();}


function packagePaths(){if(state.codeShape==="hexagonal")return {api:"adapter/in/web",service:"application",domain:"domain",port:"application/port/out",adapter:"adapter/out"};if(state.codeShape==="layered")return {api:"api",service:"application",domain:"domain",port:"infrastructure/port",adapter:"infrastructure"};return {api:"modules/workitems/api",service:"modules/workitems/application",domain:"modules/workitems/domain",port:"modules/workitems/port/out",adapter:"modules/workitems/adapter/out"};}
function packageName(path){return "com.eniglio.architecture."+path.replaceAll("/",".");}
function javaFiles(){const paths=packagePaths(),apiPkg=packageName(paths.api),servicePkg=packageName(paths.service),domainPkg=packageName(paths.domain),portPkg=packageName(paths.port),adapterPkg=packageName(paths.adapter),sourceRoot="src/main/java/",packageRoot=sourceRoot+"com/eniglio/architecture/",files={};const header=pkg=>"package "+pkg+";\n\n";
files[packageRoot+"ArchitectureApplication.java"]='package com.eniglio.architecture;\n\nimport org.springframework.boot.SpringApplication;\nimport org.springframework.boot.autoconfigure.SpringBootApplication;\n\n@SpringBootApplication\npublic class ArchitectureApplication {\n    public static void main(String[] args) {\n        SpringApplication.run(ArchitectureApplication.class, args);\n    }\n}\n';
files[packageRoot+paths.domain+"/WorkItem.java"]=header(domainPkg)+'import java.time.Instant;\nimport java.util.UUID;\n\npublic record WorkItem(UUID id, String title, Instant createdAt) {\n    public WorkItem {\n        if (id == null || title == null || title.isBlank() || createdAt == null) {\n            throw new IllegalArgumentException("A work item needs an id, title, and creation time.");\n        }\n    }\n}\n';
files[packageRoot+paths.port+"/WorkItemRepository.java"]=header(portPkg)+'import '+domainPkg+'.WorkItem;\nimport java.util.Optional;\nimport java.util.UUID;\n\npublic interface WorkItemRepository {\n    WorkItem save(WorkItem item);\n    Optional<WorkItem> findById(UUID id);\n}\n';
if(state.communication==="async")files[packageRoot+paths.port+"/WorkItemEventPublisher.java"]=header(portPkg)+'import '+domainPkg+'.WorkItem;\n\npublic interface WorkItemEventPublisher {\n    void publishCreated(WorkItem item);\n}\n';
if(state.storage!=="postgres"){files[packageRoot+paths.adapter+"/InMemoryWorkItemRepository.java"]=header(adapterPkg)+'import '+domainPkg+'.WorkItem;\nimport '+portPkg+'.WorkItemRepository;\nimport org.springframework.stereotype.Repository;\nimport java.util.Optional;\nimport java.util.UUID;\nimport java.util.concurrent.ConcurrentHashMap;\n\n@Repository\npublic class InMemoryWorkItemRepository implements WorkItemRepository {\n    private final ConcurrentHashMap<UUID, WorkItem> items = new ConcurrentHashMap<>();\n    @Override public WorkItem save(WorkItem item) { items.put(item.id(), item); return item; }\n    @Override public Optional<WorkItem> findById(UUID id) { return Optional.ofNullable(items.get(id)); }\n}\n';}
else{
files[packageRoot+paths.adapter+"/WorkItemEntity.java"]=header(adapterPkg)+'import jakarta.persistence.Entity;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.Table;\nimport jakarta.persistence.Column;\nimport java.time.Instant;\nimport java.util.UUID;\n\n@Entity\n@Table(name = "work_items")\npublic class WorkItemEntity {\n    @Id private UUID id;\n    @Column(nullable = false, length = 180) private String title;\n    @Column(nullable = false) private Instant createdAt;\n    protected WorkItemEntity() {}\n    public WorkItemEntity(UUID id, String title, Instant createdAt) { this.id = id; this.title = title; this.createdAt = createdAt; }\n    public UUID getId() { return id; }\n    public String getTitle() { return title; }\n    public Instant getCreatedAt() { return createdAt; }\n}\n';
files[packageRoot+paths.adapter+"/SpringDataWorkItemRepository.java"]=header(adapterPkg)+'import org.springframework.data.jpa.repository.JpaRepository;\nimport java.util.UUID;\n\npublic interface SpringDataWorkItemRepository extends JpaRepository<WorkItemEntity, UUID> {}\n';
files[packageRoot+paths.adapter+"/PostgresWorkItemRepository.java"]=header(adapterPkg)+'import '+domainPkg+'.WorkItem;\nimport '+portPkg+'.WorkItemRepository;\nimport org.springframework.stereotype.Repository;\nimport java.util.Optional;\nimport java.util.UUID;\n\n@Repository\npublic class PostgresWorkItemRepository implements WorkItemRepository {\n    private final SpringDataWorkItemRepository delegate;\n    public PostgresWorkItemRepository(SpringDataWorkItemRepository delegate) { this.delegate = delegate; }\n    @Override public WorkItem save(WorkItem item) {\n        WorkItemEntity saved = delegate.save(new WorkItemEntity(item.id(), item.title(), item.createdAt()));\n        return new WorkItem(saved.getId(), saved.getTitle(), saved.getCreatedAt());\n    }\n    @Override public Optional<WorkItem> findById(UUID id) {\n        return delegate.findById(id).map(row -> new WorkItem(row.getId(), row.getTitle(), row.getCreatedAt()));\n    }\n}\n';
}
let service='package '+servicePkg+';\n\nimport '+domainPkg+'.WorkItem;\nimport '+portPkg+'.WorkItemRepository;\nimport org.springframework.stereotype.Service;\nimport java.time.Instant;\nimport java.util.Optional;\nimport java.util.UUID;\n\n@Service\npublic class CreateWorkItemService {\n    private final WorkItemRepository repository;\n';
if(state.communication==="async")service+='    private final '+portPkg+'.WorkItemEventPublisher eventPublisher;\n';
service+='\n    public CreateWorkItemService(WorkItemRepository repository'+(state.communication==="async"?", "+portPkg+".WorkItemEventPublisher eventPublisher":"")+") {\n        this.repository = repository;\n"+(state.communication==="async"?"        this.eventPublisher = eventPublisher;\n":"")+"    }\n\n    public WorkItem create(String title) {\n        if (title == null || title.isBlank() || title.length() > 180) {\n            throw new IllegalArgumentException(\"Title must contain 1 to 180 characters.\");\n        }\n        WorkItem item = new WorkItem(UUID.randomUUID(), title.trim(), Instant.now());\n        WorkItem saved = repository.save(item);\n"+(state.communication==="async"?"        eventPublisher.publishCreated(saved);\n":"")+"        return saved;\n    }\n\n    public Optional<WorkItem> find(UUID id) { return repository.findById(id); }\n}\n";
files[packageRoot+paths.service+"/CreateWorkItemService.java"]=service;
files[packageRoot+paths.api+"/WorkItemController.java"]=header(apiPkg)+'import '+domainPkg+'.WorkItem;\nimport '+servicePkg+'.CreateWorkItemService;\nimport jakarta.validation.Valid;\nimport jakarta.validation.constraints.NotBlank;\nimport jakarta.validation.constraints.Size;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.web.bind.annotation.*;\nimport java.time.Instant;\nimport java.util.UUID;\n\n@RestController\n@RequestMapping("/api/v1/work-items")\npublic class WorkItemController {\n    private final CreateWorkItemService service;\n    public WorkItemController(CreateWorkItemService service) { this.service = service; }\n\n    @PostMapping\n    public ResponseEntity<WorkItemResponse> create(@Valid @RequestBody CreateWorkItemRequest request) {\n        WorkItem item = service.create(request.title());\n        return ResponseEntity.status(HttpStatus.CREATED).body(WorkItemResponse.from(item));\n    }\n    @GetMapping("/{id}")\n    public ResponseEntity<WorkItemResponse> find(@PathVariable UUID id) {\n        return service.find(id).map(item -> ResponseEntity.ok(WorkItemResponse.from(item)))\n            .orElseGet(() -> ResponseEntity.notFound().build());\n    }\n    public record CreateWorkItemRequest(@NotBlank @Size(max = 180) String title) {}\n    public record WorkItemResponse(UUID id, String title, Instant createdAt) {\n        static WorkItemResponse from(WorkItem item) { return new WorkItemResponse(item.id(), item.title(), item.createdAt()); }\n    }\n}\n';
files[packageRoot+"security/KeycloakSecurityConfig.java"]="package com.eniglio.architecture.security;\n\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport org.springframework.web.cors.CorsConfiguration;\nimport org.springframework.web.cors.CorsConfigurationSource;\nimport org.springframework.web.cors.UrlBasedCorsConfigurationSource;\nimport java.util.List;\nimport org.springframework.security.config.Customizer;\nimport org.springframework.security.config.annotation.web.builders.HttpSecurity;\nimport org.springframework.security.config.http.SessionCreationPolicy;\nimport org.springframework.security.oauth2.core.DelegatingOAuth2TokenValidator;\nimport org.springframework.security.oauth2.core.OAuth2Error;\nimport org.springframework.security.oauth2.core.OAuth2TokenValidator;\nimport org.springframework.security.oauth2.core.OAuth2TokenValidatorResult;\nimport org.springframework.security.oauth2.jwt.Jwt;\nimport org.springframework.security.oauth2.jwt.JwtDecoder;\nimport org.springframework.security.oauth2.jwt.JwtValidators;\nimport org.springframework.security.oauth2.jwt.NimbusJwtDecoder;\nimport org.springframework.security.web.SecurityFilterChain;\n\n@Configuration\npublic class KeycloakSecurityConfig {\n    @Bean\n    JwtDecoder jwtDecoder(@Value(\"${spring.security.oauth2.resourceserver.jwt.issuer-uri}\") String issuer) {\n        NimbusJwtDecoder decoder = NimbusJwtDecoder.withIssuerLocation(issuer).build();\n        OAuth2TokenValidator<Jwt> audience = jwt -> jwt.getAudience().contains(\"studio-api\")\n            ? OAuth2TokenValidatorResult.success()\n            : OAuth2TokenValidatorResult.failure(new OAuth2Error(\"invalid_token\", \"Required audience is missing\", null));\n        decoder.setJwtValidator(new DelegatingOAuth2TokenValidator<>(\n            JwtValidators.createDefaultWithIssuer(issuer), audience));\n        return decoder;\n    }\n\n    @Bean\n    CorsConfigurationSource corsConfigurationSource(@Value(\"${app.cors.allowed-origins}\") List<String> origins) {\n        CorsConfiguration cors = new CorsConfiguration();\n        cors.setAllowedOrigins(origins);\n        cors.setAllowedMethods(List.of(\"GET\", \"POST\", \"PUT\", \"PATCH\", \"DELETE\", \"OPTIONS\"));\n        cors.setAllowedHeaders(List.of(\"Authorization\", \"Content-Type\", \"Idempotency-Key\"));\n        cors.setAllowCredentials(false);\n        UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();\n        source.registerCorsConfiguration(\"/api/**\", cors);\n        return source;\n    }\n\n    @Bean\n    SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {\n        return http\n            .cors(Customizer.withDefaults())\n            .csrf(csrf -> csrf.ignoringRequestMatchers(\"/api/**\"))\n            .sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))\n            .authorizeHttpRequests(auth -> auth\n                .requestMatchers(\"/actuator/health\", \"/api/v1/public/health\").permitAll()\n                .requestMatchers(\"/api/**\").authenticated()\n                .anyRequest().denyAll())\n            .oauth2ResourceServer(oauth2 -> oauth2.jwt(Customizer.withDefaults()))\n            .build();\n    }\n}\n";
files[packageRoot+"api/PublicHealthController.java"]='package com.eniglio.architecture.api;\n\nimport org.springframework.web.bind.annotation.GetMapping;\nimport org.springframework.web.bind.annotation.RestController;\nimport java.util.Map;\n\n@RestController\npublic class PublicHealthController {\n    @GetMapping("/api/v1/public/health")\n    public Map<String, String> health() { return Map.of("status", "UP"); }\n}\n';
if(state.communication==="async"){
files[packageRoot+paths.domain+"/WorkItemCreated.java"]=header(domainPkg)+'import java.time.Instant;\nimport java.util.UUID;\n\npublic record WorkItemCreated(UUID id, String title, Instant occurredAt) {}\n';
files[packageRoot+paths.adapter+"/rabbit/RabbitWorkItemEventPublisher.java"]=header(adapterPkg+".rabbit")+'import '+domainPkg+'.WorkItem;\nimport '+domainPkg+'.WorkItemCreated;\nimport '+portPkg+'.WorkItemEventPublisher;\nimport org.springframework.amqp.rabbit.core.RabbitTemplate;\nimport org.springframework.stereotype.Component;\nimport java.time.Instant;\n\n@Component\npublic class RabbitWorkItemEventPublisher implements WorkItemEventPublisher {\n    private final RabbitTemplate rabbitTemplate;\n    public RabbitWorkItemEventPublisher(RabbitTemplate rabbitTemplate) { this.rabbitTemplate = rabbitTemplate; }\n    @Override public void publishCreated(WorkItem item) {\n        rabbitTemplate.convertAndSend("work-items.exchange", "work-items.created", new WorkItemCreated(item.id(), item.title(), Instant.now()));\n    }\n}\n';
files[packageRoot+paths.adapter+"/rabbit/WorkItemCreatedListener.java"]=header(adapterPkg+".rabbit")+'import '+domainPkg+'.WorkItemCreated;\nimport org.springframework.amqp.rabbit.annotation.RabbitListener;\nimport org.springframework.stereotype.Component;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\n\n@Component\npublic class WorkItemCreatedListener {\n    private static final Logger log = LoggerFactory.getLogger(WorkItemCreatedListener.class);\n    @RabbitListener(queues = "work-items.created")\n    public void onCreated(WorkItemCreated event) { log.info("Received work item created event: {}", event.id()); }\n}\n';
files[packageRoot+"messaging/RabbitMessagingConfig.java"]='package com.eniglio.architecture.messaging;\n\nimport org.springframework.amqp.core.Binding;\nimport org.springframework.amqp.core.BindingBuilder;\nimport org.springframework.amqp.core.DirectExchange;\nimport org.springframework.amqp.core.Queue;\nimport org.springframework.amqp.core.QueueBuilder;\nimport org.springframework.amqp.support.converter.Jackson2JsonMessageConverter;\nimport org.springframework.amqp.support.converter.MessageConverter;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\n\n@Configuration\npublic class RabbitMessagingConfig {\n    @Bean DirectExchange workItemsExchange() { return new DirectExchange("work-items.exchange", true, false); }\n    @Bean Queue workItemsCreatedQueue() { return QueueBuilder.durable("work-items.created").build(); }\n    @Bean Binding workItemsBinding(Queue workItemsCreatedQueue, DirectExchange workItemsExchange) {\n        return BindingBuilder.bind(workItemsCreatedQueue).to(workItemsExchange).with("work-items.created");\n    }\n    @Bean MessageConverter messageConverter() { return new Jackson2JsonMessageConverter(); }\n}\n';
}
return files;}


function makeReadme(root,jpa,asyncMode){
  const en=state.lang==="en",micro=state.topology==="microservices",external=state.storage==="external";
  const heading=en?"Architecture choices":"Decisões de arquitetura",run=en?"## Start locally":"## Executar localmente";
  const steps=en?[
    "1. Copy `.env.example` to `.env` and replace the local development passwords.",
    "2. Start dependencies with `docker compose up -d`. Keycloak listens on `http://localhost:8081`; the development realm imports automatically.",
    "3. Run the API with Java 21 and Maven 3.6.3 or later using `sh run-api.sh` (macOS/Linux) or `./run-api.ps1` (PowerShell). Both scripts load `.env` into the API process.",
    "4. Check `GET http://localhost:8080/api/v1/public/health`. Other `/api/**` requests require a signed Keycloak bearer token with the expected issuer and `studio-api` audience."
  ]:[
    "1. Copie `.env.example` para `.env` e troque as senhas locais de desenvolvimento.",
    "2. Inicie as dependências com `docker compose up -d`. O Keycloak fica em `http://localhost:8081`; o realm de desenvolvimento é importado automaticamente.",
    "3. Execute a API com Java 21 e Maven 3.6.3 ou posterior usando `sh run-api.sh` (macOS/Linux) ou `./run-api.ps1` (PowerShell). Os dois scripts carregam `.env` no processo da API.",
    "4. Confira `GET http://localhost:8080/api/v1/public/health`. As demais rotas `/api/**` exigem bearer token assinado pelo Keycloak com issuer e audience `studio-api`."
  ];
  const identity=en?"Keycloak through OpenID Connect":"Keycloak via OpenID Connect";
  const persistence=jpa?"PostgreSQL":(external?(en?"External store selected; generated in-memory adapter is a temporary placeholder and loses data":"Armazenamento externo escolhido; o adaptador em memória gerado é temporário e perde os dados"):(en?"In-memory sample; data is lost when the process stops":"Exemplo em memória; os dados são perdidos quando o processo para"));
  const scaffold=micro?(en?"The selected topology is microservices, but this ZIP contains one independently deployable Java service slice. It does not invent service boundaries, contracts, deployment manifests, or data ownership that were not specified.":"A topologia selecionada é microserviços, mas este ZIP contém uma fatia de serviço Java implantável de forma independente. Ele não inventa fronteiras, contratos, manifestos de implantação ou propriedade de dados que não foram especificados."):(en?"The generated application is one modular Java service.":"A aplicação gerada é um serviço Java modular.");
  const devWarning=en?"Use the `architecture-web` public client with Authorization Code + PKCE; its default redirect origins are localhost ports 3000 and 5173. Add the origin of your actual front end to both the realm client and `CORS_ALLOWED_ORIGINS`. The imported realm and Keycloak `start-dev` mode are for local development only. The realm includes a temporary demo user whose first login requires a password change. Do not use these settings in a shared or production environment. Before deployment, configure HTTPS, managed secrets, durable Keycloak storage, role/scope authorization, audit and retention policies, secret rotation, and an operational runbook. The API validates token signature, issuer, expiry, and `studio-api` audience; it does not yet authorize business actions by role or scope.":"Use o cliente público `architecture-web` com Authorization Code + PKCE; os endereços de redirecionamento padrão são as portas localhost 3000 e 5173. Adicione a origem real da aplicação cliente ao client do realm e a `CORS_ALLOWED_ORIGINS`. O realm importado e o modo `start-dev` do Keycloak servem apenas para desenvolvimento local. O realm inclui um usuário temporário de demonstração que deve trocar a senha no primeiro acesso. Não use essas configurações em ambiente compartilhado ou produção. Antes de publicar, configure HTTPS, segredos gerenciados, armazenamento durável do Keycloak, autorização por roles/scopes, políticas de auditoria e retenção, rotação de segredos e runbook operacional. A API valida assinatura, issuer, expiração e audience `studio-api`; ainda não autoriza ações de negócio por role ou scope.";
  const dataNote=jpa?(en?"PostgreSQL schema auto-update is enabled only to simplify this local scaffold. Replace it with a migration tool and reviewed migration scripts before deployment.":"A atualização automática do schema PostgreSQL existe apenas para simplificar este esqueleto local. Adote uma ferramenta de migração e scripts revisados antes da implantação."):(external?(en?"An existing database was selected, but its vendor and schema were not provided. The generated in-memory adapter keeps the sample runnable and is not a substitute for that database. Implement and validate an adapter for the approved platform.":"Um banco existente foi selecionado, mas seu fornecedor e schema não foram informados. O adaptador em memória mantém o exemplo executável e não substitui esse banco. Implemente e valide um adaptador para a plataforma aprovada."):(en?"The in-memory repository is not durable and is only appropriate for a local demonstration.":"O repositório em memória não é durável e serve apenas para demonstração local."));
  const messaging=asyncMode?(en?"RabbitMQ is included as an event-flow example. Define an outbox, idempotency keys, retry limits, dead-letter policy, ordering, and reconciliation before relying on it for business-critical delivery.":"O RabbitMQ está incluído como exemplo de fluxo por eventos. Defina outbox, chaves de idempotência, limite de tentativas, política de dead letter, ordenação e reconciliação antes de depender dele para entrega crítica ao negócio."):"";
  const sample=en?"The sample `WorkItem` use case is generic. Replace it with the domain behavior from `architecture/brief.md`.":"O caso de uso genérico `WorkItem` é apenas um exemplo. Substitua-o pelo comportamento de domínio descrito em `architecture/brief.md`.";
  return "# "+(state.projectName||"Java Architecture Starter")+"\n\n"+(en?"Generated by Eniglio Architecture Studio. This is a reviewable scaffold, not production-ready software.":"Gerado pelo Eniglio Architecture Studio. Este é um esqueleto para revisão, não um sistema pronto para produção.")+"\n\n## "+heading+"\n\n- "+(en?"Deployment":"Implantação")+": "+labels().topology+"\n- "+(en?"Code organization":"Organização do código")+": "+labels().shape+"\n- "+(en?"Communication":"Comunicação")+": "+labels().communication+"\n- "+(en?"Persistence":"Persistência")+": "+persistence+"\n- "+(en?"Identity provider":"Provedor de identidade")+": "+identity+"\n\n"+scaffold+"\n\n"+run+"\n\n"+steps.join("\n")+"\n\n"+devWarning+"\n\n"+dataNote+(messaging?"\n\n"+messaging:"")+"\n\n"+sample+"\n\n## "+(en?"Generated artifacts":"Artefatos gerados")+"\n\n- `architecture/brief.md` — "+(en?"entered requirements and assumptions":"requisitos informados e premissas")+".\n- `architecture/decisions.md` — "+(en?"architecture decisions and trade-offs":"decisões arquiteturais e trade-offs")+".\n- `architecture/c4-context.svg`, `architecture/c4-containers.svg`, `architecture/sequence.svg` — "+(en?"diagrams to review and edit":"diagramas para revisar e editar")+".\n";
}
function envVar(key){return String.fromCharCode(36)+"{"+key+"}";}
