function renderStarter(){const files=projectFiles(),paths=Object.keys(files),root=safeName(state.projectName),tree=paths.slice(0,12).map((path,i)=>"<li class=\""+(i>0?"indent":"")+"\">"+escapeHtml(path.replace(root+"/",""))+"</li>").join(""),sample=files[paths.find(path=>path.endsWith("KeycloakSecurityConfig.java"))];return "<div class=\"artifact-toolbar\"><strong>"+escapeHtml(t("starterTitle"))+"</strong><button type=\"button\" data-copy-code>"+(state.lang==="en"?"Copy security config":"Copiar config. de segurança")+"</button></div><div class=\"starter-summary\"><div class=\"file-tree\"><strong>"+escapeHtml(root)+"/</strong><ul>"+tree+"</ul></div><div class=\"code-preview\"><pre><code>"+escapeHtml(sample)+"</code></pre></div><p class=\"starter-footnote\">"+escapeHtml(t("starterHint"))+"<br>"+escapeHtml(t("fileNote"))+"</p></div>";}
function copyText(text){if(navigator.clipboard?.writeText)navigator.clipboard.writeText(text).then(()=>toast(t("toastCopied"))).catch(()=>fallbackCopy(text));else fallbackCopy(text);}
function fallbackCopy(text){const area=document.createElement("textarea");area.value=text;area.style.position="fixed";area.style.opacity="0";document.body.append(area);area.select();document.execCommand("copy");area.remove();toast(t("toastCopied"));}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function downloadSvg(){downloadBlob(new Blob([lastSvg],{type:"image/svg+xml;charset=utf-8"}),safeName(state.projectName)+"-"+state.artifact+".svg");}
const crcTable=(()=>{const table=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=(c&1)?0xedb88320^(c>>>1):c>>>1;table[n]=c>>>0;}return table;})();
function crc32(bytes){let crc=0xffffffff;for(const byte of bytes)crc=crcTable[(crc^byte)&255]^(crc>>>8);return (crc^0xffffffff)>>>0;}
function makeZip(files){const encoder=new TextEncoder(),local=[],central=[];let offset=0;const now=new Date(),dosTime=(now.getHours()<<11)|(now.getMinutes()<<5)|(now.getSeconds()>>1),dosDate=((Math.max(1980,now.getFullYear())-1980)<<9)|((now.getMonth()+1)<<5)|now.getDate();function u16(view,pos,value){view.setUint16(pos,value,true);}function u32(view,pos,value){view.setUint32(pos,value,true);}Object.entries(files).forEach(([name,content])=>{const nameBytes=encoder.encode(name),data=encoder.encode(content),crc=crc32(data),lh=new Uint8Array(30+nameBytes.length),lv=new DataView(lh.buffer);u32(lv,0,0x04034b50);u16(lv,4,20);u16(lv,6,0x0800);u16(lv,8,0);u16(lv,10,dosTime);u16(lv,12,dosDate);u32(lv,14,crc);u32(lv,18,data.length);u32(lv,22,data.length);u16(lv,26,nameBytes.length);u16(lv,28,0);lh.set(nameBytes,30);local.push(lh,data);const ch=new Uint8Array(46+nameBytes.length),cv=new DataView(ch.buffer);u32(cv,0,0x02014b50);u16(cv,4,20);u16(cv,6,20);u16(cv,8,0x0800);u16(cv,10,0);u16(cv,12,dosTime);u16(cv,14,dosDate);u32(cv,16,crc);u32(cv,20,data.length);u32(cv,24,data.length);u16(cv,28,nameBytes.length);u16(cv,30,0);u16(cv,32,0);u16(cv,34,0);u16(cv,36,0);u32(cv,38,0);u32(cv,42,offset);ch.set(nameBytes,46);central.push(ch);offset+=lh.length+data.length;});const centralSize=central.reduce((sum,part)=>sum+part.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);u32(ev,0,0x06054b50);u16(ev,4,0);u16(ev,6,0);u16(ev,8,Object.keys(files).length);u16(ev,10,Object.keys(files).length);u32(ev,12,centralSize);u32(ev,16,offset);u16(ev,20,0);return new Blob([...local,...central,end],{type:"application/zip"});}
function downloadProject(){readInputs();downloadBlob(makeZip(projectFiles()),safeName(state.projectName)+"-architecture-starter.zip");toast(t("toastZip"));}


function setConnected(value){ollamaConnected=value;$("#ollamaStatus").classList.toggle("is-connected",value);$("#ollamaMessage").textContent=value?t("connected"):t("ollamaDisconnected");$("#ollamaMessage").classList.toggle("connected",value);}
async function detectModels(){const url=$("#ollamaUrl").value.trim().replace(/\/+$/,"");state.ollamaUrl=url;$("#ollamaMessage").textContent=state.lang==="en"?"Checking…":"Verificando…";try{const response=await fetch(url+"/api/tags");if(!response.ok)throw new Error("status");const data=await response.json(),models=data.models||[],select=$("#ollamaModel");select.innerHTML="";models.forEach(model=>{const option=document.createElement("option");option.value=model.name;option.textContent=model.name;select.append(option);});if(!models.length)throw new Error("no-models");if(models.some(model=>model.name===state.ollamaModel))select.value=state.ollamaModel;state.ollamaModel=select.value;setConnected(true);scheduleSave();}catch{setConnected(false);$("#ollamaMessage").textContent=t("connectionFailed");}}
function resetProject(){if(!confirm(state.lang==="en"?"Clear the local draft and start a new project?":"Apagar o rascunho local e começar outro projeto?"))return;try{localStorage.removeItem(STORE_KEY);}catch{}location.href=location.pathname+(state.lang==="en"?"?lang=en":"");}
function fillExample(kind){const examples=copy[state.lang].exampleBrief;$("#brief").value=examples[kind]||"";if(kind==="orders")$("#projectName").value=state.lang==="en"?"Order and payment flow":"Fluxo de pedidos e pagamentos";if(kind==="docs"){$("#projectName").value=state.lang==="en"?"Contract review assistant":"Assistente de análise contratual";$("#sensitivity").value="regulated";}if(kind==="requests")$("#projectName").value=state.lang==="en"?"Access request service":"Serviço de solicitações de acesso";readInputs();updateCounters();scheduleSave();$("#brief").focus();}
function bindEvents(){
  $$(".rail-step").forEach(button=>button.addEventListener("click",()=>setStep(Number(button.dataset.step))));
  $$(".next-step").forEach(button=>button.addEventListener("click",()=>{readInputs();setStep(Number(button.dataset.next));}));
  $$(".previous-step").forEach(button=>button.addEventListener("click",()=>setStep(Number(button.dataset.prev))));
  $$("input,select,textarea").forEach(field=>field.addEventListener("input",()=>{readInputs();if(field.id==="brief")updateCounters();updateEconomics();renderRationale();scheduleSave();}));
  $$("input[type=radio]").forEach(field=>field.addEventListener("change",()=>{readInputs();renderRationale();scheduleSave();}));
  $$(".example-chip").forEach(button=>button.addEventListener("click",()=>fillExample(button.dataset.example)));
  $("#analyzeBrief").addEventListener("click",analyzeBrief);
  $("#closeAdvisor").addEventListener("click",()=>$("#briefAdvisor").hidden=true);
  $("#advisorForm").addEventListener("submit",askAdvisor);
  $$(".artifact-tab").forEach(button=>button.addEventListener("click",()=>renderArtifact(button.dataset.artifact)));
  $("#artifactPanel").addEventListener("click",event=>{if(event.target.closest("[data-diagram-action=copy]"))copyText(lastSvg);if(event.target.closest("[data-diagram-action=download]"))downloadSvg();if(event.target.closest("[data-copy-decisions]"))copyText(markdownDecisions());if(event.target.closest("[data-copy-code]")){const files=javaFiles();copyText(files[Object.keys(files).find(key=>key.endsWith("KeycloakSecurityConfig.java"))]);}});
  $("#downloadProject").addEventListener("click",downloadProject);
  $("#startOver").addEventListener("click",resetProject);
  $("#openOllama").addEventListener("click",()=>$("#ollamaDialog").showModal());
  $("#doneOllama").addEventListener("click",()=>{$("#ollamaDialog").close();state.ollamaUrl=$("#ollamaUrl").value;state.ollamaModel=$("#ollamaModel").value;scheduleSave();});
  $("#detectModels").addEventListener("click",detectModels);
  $("#ollamaUrl").addEventListener("change",()=>{setConnected(false);state.ollamaUrl=$("#ollamaUrl").value;scheduleSave();});
  $("#ollamaModel").addEventListener("change",()=>{state.ollamaModel=$("#ollamaModel").value;scheduleSave();});
  $("#languageToggle").addEventListener("click",()=>{state.lang=state.lang==="en"?"pt":"en";applyLanguage();updateEconomics();renderChat();if(state.advisor)renderMap(state.advisor,state.advisor.origin);if(state.step===2)renderRationale();if(state.step===3){renderRecommendation();renderArtifact(state.artifact);}scheduleSave();});
  $("#projectName").addEventListener("input",()=>{state.projectName=$("#projectName").value;$("#projectNamePreview").textContent=state.projectName|| (state.lang==="en"?"New project":"Novo projeto");scheduleSave();});
  document.addEventListener("keydown",event=>{if(event.key==="Escape"&&$("#ollamaDialog").open)$("#ollamaDialog").close();});
}
applyStateToInputs();
bindEvents();
setStep(0);
renderChat();
updateEconomics();
